<template><section class="api-preview" aria-label="接口概览"><header><h3>接口概览</h3><a-button type="text" size="small" aria-label="关闭接口概览" @click="$emit('close')">×</a-button></header><dl class="api-record-meta"><div><dt>所属目录</dt><dd>{{ record.collection_name || '未记录' }}</dd></div><div><dt>创建人</dt><dd>{{ record.creator_name || '未记录' }}</dd></div><div><dt>更新时间</dt><dd>{{ new Date(record.updated_at).toLocaleString('zh-CN') }}</dd></div></dl><h5>接口说明</h5><p>{{ record.description || '尚未填写接口说明，可在接口列表中编辑。' }}</p><h5>请求体字段</h5><div v-for="field in fields" :key="field.name" class="api-body-field"><strong>{{ field.name }}</strong><span>{{ field.type }}</span></div><p v-if="!fields.length">当前请求体没有可展示的 JSON 字段。</p><p class="api-preview-hint">字段类型根据当前请求体推断，实际约束以接口契约和断言配置为准。</p><h5>验证配置</h5><p>{{ record.assertion_specs?.length || record.assertions?.length || 0 }} 条已保存断言 · {{ record.extractor_specs?.length || 0 }} 条提取规则</p><footer class="api-preview__footer"><router-link class="arco-btn arco-btn-outline arco-btn-size-default" to="/api-automation?tab=test-cases">测试用例</router-link><a-button type="primary" :loading="saving" @click="$emit('save')">保存接口</a-button></footer></section></template>
<script setup lang="ts">
import { computed } from 'vue'
import type { ApiRequest } from '../types'
const props=defineProps<{record:ApiRequest;body:unknown;saving?:boolean}>()
defineEmits<{close:[];save:[]}>()
const fields=computed(()=>{try{const value=typeof props.body==='string'?JSON.parse(props.body):props.body;return value && typeof value==='object' && !Array.isArray(value) ? Object.entries(value).map(([name,item])=>({name,type:item===null ? 'null' : Array.isArray(item) ? '数组' : typeof item==='number' ? Number.isInteger(item) ? '整数' : '数字' : typeof item==='boolean' ? '布尔值' : typeof item==='object' ? '对象' : '字符串'})) : []}catch{return []}})
</script>
